function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 100000) return 'nums needs 2 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1e9 || v > 1e9)) return 'Each value of nums is an integer between -10^9 and 10^9.';
  if (!Number.isInteger(k) || k < 1 || k > 1e9) return 'k is an integer between 1 and 10^9.';
  return null;
}

