function maximumSubarraySum(nums, k) {
  const minPrefix = new Map();
  let prefix = 0;
  let best = -Infinity;

  for (const num of nums) {
    if (!minPrefix.has(num) || prefix < minPrefix.get(num)) {
      minPrefix.set(num, prefix);
    }
    prefix += num;
    for (const start of [num - k, num + k]) {
      if (minPrefix.has(start)) {
        best = Math.max(best, prefix - minPrefix.get(start));
      }
    }
  }
  return best === -Infinity ? 0 : best;
}

