function maximumSubarraySum(nums, k) {
  let best = null;
  for (let i = 0; i < nums.length; i++) {
    let total = 0;
    for (let j = i; j < nums.length; j++) {
      total += nums[j];
      if (Math.abs(nums[i] - nums[j]) === k && (best === null || total > best)) best = total;
    }
  }
  return best === null ? 0 : best;
}

