function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(2, 9);
    const shape = int(0, 3);
    if (shape === 0) {
      // Spread values: good subarrays are rare, so 0 is a common answer.
      return [Array.from({ length: n }, () => int(-1000000000, 1000000000)), int(1, 1000000000)];
    }
    if (shape === 1) {
      // Only negative values, so the best good sum is usually negative.
      return [Array.from({ length: n }, () => int(-6, -1)), int(1, 4)];
    }
    const scale = shape === 2 ? 1 : 100000000;
    return [Array.from({ length: n }, () => int(-5, 5) * scale), int(1, 5) * scale];
  }
  const n = 2000;
  const shape = int(0, 2);
  if (shape === 0) {
    return [Array.from({ length: n }, () => int(-1000000000, 1000000000)), int(1, 1000000000)];
  }
  const scale = 10000000;
  const low = shape === 1 ? -100 : -60;
  return [Array.from({ length: n }, () => int(low, 100) * scale), int(1, 50) * scale];
}
